    "tagline": "Liqueur made from the maceration of ginger roots balanced by a touch of vanilla",
    "lede": "Ginger is part of the Zingiberaceae family, which also includes turmeric, cardamom, and galangal. Ginger is native to Maritime Southeast Asia and was probably first domesticated by Austronesian peoples. Ginger is one of the first spices to be exported from Asia, arriving in Europe with the spice trade, and was used by the ancient Greeks and Romans. The flavour of ginger is characterized by a unique combination of warm notes, lemon/citrus notes, and earthy notes. Ginger is an ingredient that has many properties and health benefits such as antioxidants, strengthening the immune system and digestion, among others. The growing interest in ginger in beverages is driven by tea in the winter, and ginger beer and ginger ale in the summer. Ginger is potent, but it pairs well with other flavours like blackberry, honey, turmeric, lemon, cinnamon, and fennel.",
